import java.util.*;
import java.io.*;
import java.math.BigInteger;

public class FFT {
    FastScanner in;
    PrintWriter out;
    boolean systemIO = true;

    static class Vector {
        static final int SZ = 1 << 20;
        long[] v;

        Vector(long[] a) {
            v = new long[SZ];
            for (int i = 0; i < a.length; i++) {
                v[i] = a[i];
            }
        }

        long[] fft() {
            return dft(0, 1, true);
        }

        long[] ifft() {
            long[] x = dft(0, 1, false);
            for (int i = 0; i < x.length; i++) {
                x[i] = x[i] * szinv % MOD;
            }
            return x;
        }

        long[] dft(int first, int pow, boolean straight) {
            if (pow == SZ) {
                return new long[]{v[first]};
            }
            long[] even = dft(first, 2 * pow, straight);
            long[] odd = dft(first + pow, 2 * pow, straight);
            int n = even.length;
            long[] result = new long[2 * n];
            for (int i = 0; i < n; i++) {
                long twiddle = straight ? warr[i * pow] : winvarr[i * pow];
                result[i] = (even[i] + twiddle * odd[i]) % MOD;
            }
            for (int i = 0; i < n; i++) {
                long twiddle = straight ? warr[i * pow] : winvarr[i * pow];
                result[n + i] = ((even[i] - twiddle * odd[i]) % MOD + MOD) % MOD;
            }
            return result;
        }
    }

    static long MOD = 998244353;
    static long W = 646;
    static long[] warr = new long[1 << 20];
    static long[] winvarr = new long[1 << 20];
    static long szinv;

    static {
        BigInteger modBI = BigInteger.valueOf(MOD);
        BigInteger wBI = BigInteger.valueOf(W);
        BigInteger sizeBI = BigInteger.valueOf(1 << 20);
        warr[0] = 1;
        winvarr[0] = 1;
        for (int i = 1; i < warr.length; i++) {
            warr[i] = warr[i - 1] * W % MOD;
            winvarr[i] = winvarr[i - 1] * W % MOD;
        }
        szinv = sizeBI.modInverse(modBI).longValue();
    }

    long[] fft(long[] a) {
        int sz = 1 << 20;
        long[] result = new long[sz];
        long wth = 1;
        for (int i = 0; i < sz; i++) {
            long x = 1;
            for (int j = 0; j < a.length; j++) {
                result[i] = (result[i] + a[j] * x) % MOD;
                x = x * wth % MOD;
            }
            wth = wth * W % MOD;
        }
        return result;
    }

    long[] power(long[] arr, int exp) {
        for (int i = 0; i < arr.length; i++) {
            arr[i] = modPow(arr[i], exp);
        }
        return arr;
    }

    long modPow(long base, int exp) {
        if (exp == 0) return 1;
        if (exp % 2 == 1) return modPow(base, exp - 1) * base % MOD;
        long half = modPow(base, exp / 2);
        return half * half % MOD;
    }

    void solve() {
        int n = in.nextInt();
        int k = in.nextInt();
        long[] arr = new long[10];
        for (int i = 0; i < k; i++) {
            arr[in.nextInt()] = 1;
        }
        long[] x = fft(arr);
        x = power(x, n / 2);
        Vector v = new Vector(x);
        x = v.ifft();
        long ans = 0;
        for (int i = 0; i < x.length; i++) {
            ans = (ans + x[i] * x[i]) % MOD;
        }
        out.println(ans);
    }

    void run() {
        try {
            if (systemIO) {
                in = new FastScanner(System.in);
                out = new PrintWriter(System.out);
            } else {
                in = new FastScanner(new File("input.txt"));
                out = new PrintWriter(new File("output.txt"));
            }
            solve();
            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new FFT().run();
    }
}
